(async () => {
  let ok=0, skip=0, fail=[];
  for (const t of TASKS) {
    const url = `/api/v1/projects/${t.pid}/collections/${t.col}/items/${t.postId}?locale=${t.locale}`;
    const cur = await (await fetch(url, {credentials:'include'})).json();
    const already = Object.keys(t.fields).every(f => cur[f] !== null && cur[f] !== undefined);
    if (already) { skip++; continue; }
    const body = { published: true, ...t.fields };
    for (const p of (t.preserve||[])) if (cur[p] !== null && cur[p] !== undefined) body[p] = cur[p];
    const r = await fetch(url, {method:'PUT', credentials:'include',
      headers:{'Content-Type':'application/json'}, body: JSON.stringify(body)});
    if (r.status !== 200) { fail.push(`${t.label}/${t.locale} PUT ${r.status}`); continue; }
    const after = await (await fetch(url, {credentials:'include'})).json();
    const match = Object.entries(t.fields).every(([f,v]) => JSON.stringify(after[f]) === JSON.stringify(v));
    const kept  = (t.preserve||[]).every(p => body[p] === undefined || JSON.stringify(after[p]) === JSON.stringify(body[p]));
    if (match && kept) ok++; else fail.push(`${t.label}/${t.locale} 대조불일치 match=${match} kept=${kept}`);
  }
  console.log(JSON.stringify({총건수: TASKS.length, 복구: ok, 이미채워짐: skip, 실패: fail.length, 실패목록: fail}, null, 1));
})();
